{
 "appearance_facts": [
  {
   "location": "The chart's title and subtitle.",
   "fact": "The main title reads 'Reduced Screening Referrals Across Hospitals from 2012 to 2023' and the subtitle reads 'Referral-monitoring record shown in the dashboard summary'. This text is located in the upper-left portion of the image."
  },
  {
   "location": "The plot area.",
   "fact": "A single, solid orange line graph is plotted, showing a general upward trend from left to right over the years 2012 to 2023."
  },
  {
   "location": "The data line.",
   "fact": "The line starts at a value of approximately 1,100 in 2012, fluctuates, and reaches its peak in 2022 at a value of approximately 3,600. It then shows a slight decrease in 2023 to a value of approximately 3,300."
  },
  {
   "location": "The vertical axis (y-axis).",
   "fact": "The y-axis is labeled 'Screening referrals' and has numerical tick marks at 0, 800, 1600, 2400, and 3200. Faint horizontal gridlines extend from these ticks across the plot area."
  },
  {
   "location": "The horizontal axis (x-axis).",
   "fact": "The x-axis is labeled 'Year' and has tick marks for each year from 2012 to 2023."
  },
  {
   "location": "The overall visual pattern.",
   "fact": "The visual pattern of the data line is one of significant growth, increasing from a low starting point to a much higher peak, despite the title's wording."
  }
 ],
 "printed_facts": [
  {
   "location": "Y-axis.",
   "fact": "The axis is labeled 'Screening referrals'."
  },
  {
   "location": "Y-axis ticks.",
   "fact": "The numerical labels on the y-axis are '0', '800', '1600', '2400', and '3200'."
  },
  {
   "location": "X-axis.",
   "fact": "The axis is labeled 'Year'."
  },
  {
   "location": "X-axis ticks.",
   "fact": "The numerical labels on the x-axis are '2012', '2013', '2014', '2015', '2016', '2017', '2018', '2019', '2020', '2021', '2022', and '2023'."
  },
  {
   "location": "Chart Title.",
   "fact": "The title text is 'Reduced Screening Referrals Across Hospitals from 2012 to 2023'."
  },
  {
   "location": "Chart Subtitle.",
   "fact": "The subtitle text is 'Referral-monitoring record shown in the dashboard summary'."
  }
 ]
, "public_definitions":
  [
   "The user's goal is to 'Review the screening referral dashboard and assign this record to the operational follow-up pathway that best fits the referral pattern over the reporting period.'",
   "The available options are: 'Route to growth-focused referral follow-up', 'Route to reduction-focused referral follow-up', and 'Route to standard referral monitoring'."
  ],
 "uncertain": []
}
